using MegaCrit.Sts2.Core.CardSelection;
using MegaCrit.Sts2.Core.Entities.Players;

namespace SpireDuo.SpireDuoCode.Powers;

public sealed class CatwalkKingPower : FootprintListenerPower
{ private int _turn = -1; public override PowerType Type => PowerType.Buff; public override PowerStackType StackType => PowerStackType.Single; public override async Task OnFootprintLine(PlayerChoiceContext c, CardPlay p, FootprintLine line) { int turn = Owner.Player?.PlayerCombatState?.TurnNumber ?? -1; if (line != FootprintLine.Pounce || turn == _turn) return; _turn = turn; var copy = p.Card.CreateClone(); copy.EnergyCost.SetThisTurn(0); copy.AddKeyword(CardKeyword.Exhaust); Flash(); await CardPileCmd.AddGeneratedCardToCombat(copy, PileType.Hand, Owner.Player!); } }
public sealed class FelineVelocityPower : SpireDuoPower
{ private int _attacks; public override PowerType Type => PowerType.Buff; public override PowerStackType StackType => PowerStackType.Single; public override async Task AfterCardPlayed(PlayerChoiceContext c, CardPlay p) { if (p.Card.Owner != Owner.Player || p.Card.Type != CardType.Attack || ++_attacks < Amount) return; _attacks = 0; Flash(); await CardPileCmd.Draw(c, 1, Owner.Player!); await PlayerCmd.GainEnergy(1, Owner.Player!); } }
public sealed class ImmaculateCoatPower : FootprintListenerPower
{ public override PowerType Type => PowerType.Buff; public override PowerStackType StackType => PowerStackType.Counter; public override async Task OnFootprintLine(PlayerChoiceContext c, CardPlay p, FootprintLine l) { if (l != FootprintLine.Groom) return; Flash(); await CreatureCmd.GainBlock(Owner, Amount, ValueProp.Unpowered, p); } }
public sealed class PurrfectOrderPower : SpireDuoPower
{ private int _turn = -1; private bool _ready; public override PowerType Type => PowerType.Buff; public override PowerStackType StackType => PowerStackType.Counter; public override async Task AfterCardPlayed(PlayerChoiceContext c, CardPlay p) { if (p.Card.Owner != Owner.Player) return; int turn = Owner.Player?.PlayerCombatState?.TurnNumber ?? -1; if (p.Card.Type == CardType.Skill && turn != _turn) { _turn = turn; _ready = true; } else if (p.Card.Type == CardType.Attack) _ready = false; await Task.CompletedTask; } public override decimal ModifyDamageAdditive(Creature? t, decimal a, ValueProp v, Creature? d, CardModel? card) => _ready && d == Owner && v.IsPoweredAttack() ? Amount : 0m; }
public sealed class SoftAuthorityPower : FootprintListenerPower
{ private int _turn = -1; public override PowerType Type => PowerType.Buff; public override PowerStackType StackType => PowerStackType.Single; public override async Task OnFootprintLine(PlayerChoiceContext c, CardPlay p, FootprintLine l) { int turn = Owner.Player?.PlayerCombatState?.TurnNumber ?? -1; if (l != FootprintLine.Groom || turn == _turn) return; _turn = turn; foreach (var power in Owner.Powers.Where(x => x.Type == PowerType.Debuff).ToArray()) await PowerCmd.Remove(power); if (Amount > 1) await CardPileCmd.Draw(c, 1, Owner.Player!); } }
public sealed class EbonCalendarPower : FootprintListenerPower
{ private int _turn = -1; public override PowerType Type => PowerType.Buff; public override PowerStackType StackType => PowerStackType.Single; public override async Task OnFootprintLine(PlayerChoiceContext c, CardPlay p, FootprintLine l) { int turn = Owner.Player?.PlayerCombatState?.TurnNumber ?? -1; if (l != FootprintLine.Omen || turn == _turn) return; _turn = turn; var card = (await CardSelectCmd.FromCombatPile(prefs: new CardSelectorPrefs(SelectionScreenPrompt, 1), context: c, pile: PileType.Discard.GetPile(Owner.Player!), player: Owner.Player!)).FirstOrDefault(); if (card != null) { if (Amount > 1) card.EnergyCost.SetUntilPlayed(0, true); await CardPileCmd.Add(card, PileType.Hand); } } }
public sealed class DarkMoonContractPower : SpireDuoPower
{ public override PowerType Type => PowerType.Buff; public override PowerStackType StackType => PowerStackType.Single; public override async Task AfterPlayerTurnStart(PlayerChoiceContext c, Player p) { if (p != Owner.Player) return; await FootprintStatePower.Set(c, Owner, 0, Footprint.Power); await CardPileCmd.Draw(c, 1, p); } }
public sealed class InkwellSkyPower : SpireDuoPower
{ public override PowerType Type => PowerType.Buff; public override PowerStackType StackType => PowerStackType.Counter; public override async Task AfterCardPlayed(PlayerChoiceContext c, CardPlay p) { if (p.Card.Owner != Owner.Player || p.Card.Type != CardType.Power) return; await CreatureCmd.Damage(c, Owner.CombatState!.HittableEnemies, Amount, ValueProp.Unpowered, Owner, p.Card); } }
public sealed class ConstellationNapPower : FootprintListenerPower
{ private int _turn = -1; public override PowerType Type => PowerType.Buff; public override PowerStackType StackType => PowerStackType.Single; public override async Task OnEmptySlotFilled(PlayerChoiceContext c, CardPlay p) { int turn = Owner.Player?.PlayerCombatState?.TurnNumber ?? -1; if (turn == _turn) return; _turn = turn; await PlayerCmd.GainEnergy(1, Owner.Player!); if (Amount > 1) await CardPileCmd.Draw(c, 1, Owner.Player!); } }
public sealed class SharedNightshiftPower : SpireDuoPower
{ private int _turn = -1; public override PowerType Type => PowerType.Buff; public override PowerStackType StackType => PowerStackType.Counter; public override async Task AfterCardPlayed(PlayerChoiceContext c, CardPlay p) { int turn = Owner.Player?.PlayerCombatState?.TurnNumber ?? -1; if (turn == _turn || p.Card.Owner == Owner.Player || p.Card.Owner.Creature.Side != Owner.Side || p.Card.Type != CardType.Attack) return; _turn = turn; await CreatureCmd.GainBlock(Owner, Amount, ValueProp.Unpowered, p); await CreatureCmd.GainBlock(p.Card.Owner.Creature, Amount - 2, ValueProp.Unpowered, p); } }
public sealed class SecretSignalPower : SpireDuoPower
{ public override PowerType Type => PowerType.Buff; public override PowerStackType StackType => PowerStackType.Single; public override async Task AfterCardPlayed(PlayerChoiceContext c, CardPlay p) { var state = Owner.GetPower<FootprintStatePower>(); if (state?.CompanionArmed != true || p.Card.Type != CardType.Attack || p.Card.Owner.Creature.Side != Owner.Side) return; await CardPileCmd.Draw(c, Amount, Owner.Player!); } }
public sealed class QuietPactPower : FootprintListenerPower
{ public override PowerType Type => PowerType.Buff; public override PowerStackType StackType => PowerStackType.Single; public override async Task OnCompanionResolved(PlayerChoiceContext c, CardPlay p, Creature? ally) { await PowerCmd.Apply<ArtifactPower>(c, Owner, 1, Owner, p.Card); if (ally != null && !ally.IsDead) await PowerCmd.Apply<ArtifactPower>(c, ally, 1, Owner, p.Card); if (Amount > 1) await CardPileCmd.Draw(c, 1, Owner.Player!); } }
public sealed class GuardianOfTheEavesPower : SpireDuoPower
{ private int _turn = -1; public override PowerType Type => PowerType.Buff; public override PowerStackType StackType => PowerStackType.Counter; public override async Task AfterDamageReceived(PlayerChoiceContext c, Creature t, DamageResult r, ValueProp v, Creature? dealer, CardModel? source) { int turn = Owner.Player?.PlayerCombatState?.TurnNumber ?? -1; if (turn == _turn || t.Side != Owner.Side || t == Owner || r.UnblockedDamage <= 0) return; _turn = turn; Flash(); var enemy = Owner.CombatState!.HittableEnemies.FirstOrDefault(); if (enemy != null) await CreatureCmd.Damage(c, enemy, Amount, ValueProp.Unpowered, Owner, source); } }
public sealed class NightAtlasPower : FootprintListenerPower
{ private int _turn = -1; public override PowerType Type => PowerType.Buff; public override PowerStackType StackType => PowerStackType.Single; public override async Task OnFootprintLine(PlayerChoiceContext c, CardPlay p, FootprintLine l) { int turn = Owner.Player?.PlayerCombatState?.TurnNumber ?? -1; if (turn == _turn) return; _turn = turn; await PlayerCmd.GainEnergy(1, Owner.Player!); await CardPileCmd.Draw(c, 1, Owner.Player!); if (Amount > 0) await CreatureCmd.GainBlock(Owner, Amount, ValueProp.Unpowered, p); } }
public sealed class CatOfTheThresholdPower : SpireDuoPower
{ private bool _used; public override PowerType Type => PowerType.Buff; public override PowerStackType StackType => PowerStackType.Single; public override bool ShouldDieLate(Creature creature) => creature != Owner || _used; public override Task AfterPreventingDeath(Creature creature) { _used = true; return Task.CompletedTask; } }
